public class VerifyPigLatin {
    static int fails = 0;
    static void check(String in, String expected) {
        String actual = new PigLatinTranslator().translate(in);
        if (!expected.equals(actual)) {
            fails++;
            System.out.println("FAIL: \"" + in + "\" -> \"" + actual + "\" expected \"" + expected + "\"");
        } else {
            System.out.println("ok: \"" + in + "\" -> \"" + actual + "\"");
        }
    }
    public static void main(String[] args) {
        check("apple", "appleay");
        check("ear", "earay");
        check("igloo", "iglooay");
        check("object", "objectay");
        check("under", "underay");
        check("equal", "equalay");
        check("pig", "igpay");
        check("koala", "oalakay");
        check("xenon", "enonxay");
        check("qat", "atqay");
        check("chair", "airchay");
        check("queen", "eenquay");
        check("square", "aresquay");
        check("therapy", "erapythay");
        check("thrush", "ushthray");
        check("school", "oolschay");
        check("yttria", "yttriaay");
        check("xray", "xrayay");
        check("yellow", "ellowyay");
        check("rhythm", "ythmrhay");
        check("my", "ymay");
        check("quick fast run", "ickquay astfay unray");
        System.out.println(fails == 0 ? "ALL PASS" : (fails + " FAILURES"));
        if (fails != 0) System.exit(1);
    }
}
